<script setup>
import {onMounted,ref} from 'vue';import {get,fmt,pct} from '../api/client';import MetricCard from '../components/MetricCard.vue';import DataTable from '../components/DataTable.vue'
const data=ref(null),error=ref(''),showBacktestHelp=ref(false);onMounted(async()=>{try{data.value=await get('/dashboard')}catch(e){error.value=e.message}})
const cols=[{label:'分组',key:'top_n',format:v=>`Top${v}`},{label:'上涨比例',key:'up_rate',format:pct},{label:'平均收益',key:'avg_return',format:pct,class:v=>v>0?'positive':'negative'},{label:'市场收益',key:'market_avg_return',format:pct},{label:'超额收益',key:'excess_return',format:pct,class:v=>v>0?'positive':'negative'}]
</script><template><div v-if="error" class="empty">{{error}}</div><div v-else-if="!data" class="empty">加载中…</div><template v-else><div class="grid"><MetricCard label="股票数量" :value="fmt(data.stats.stock_count,0)" sub="SH · SZ · BJ"/><MetricCard label="日线记录" :value="fmt(data.stats.daily_count,0)" :sub="`${data.stats.first_date} — ${data.stats.latest_date}`"/><MetricCard label="预测批次" :value="data.stats.prediction_runs" :sub="`最新 ${data.latest_prediction.base_date||'—'}`"/><MetricCard label="正式验证" :value="data.stats.verification_runs" sub="收盘后执行验证生成"/></div><div class="section"><div class="detail-heading"><div><h2>最新模型历史回测表现</h2><span class="backtest-caption">基于已有历史样本计算，不是收盘后的正式验证结果</span></div><button @click="showBacktestHelp=!showBacktestHelp">{{showBacktestHelp?'收起说明':'指标说明'}}</button></div><div v-if="showBacktestHelp" class="card logic-card backtest-help"><p><b>这组数据是什么：</b>生成最新预测时，模型在已有历史行情上进行的样本回测，用来初步观察模型表现；历史数据较短时结果可能偏乐观，不能代表未来收益。</p><ul><li><b>样本上涨率：</b>历史回测候选股票在下一交易日上涨的比例。</li><li><b>候选平均：</b>历史回测候选股票的次日平均收益。</li><li><b>市场平均：</b>相同回测日期内全市场股票的次日平均收益。</li><li><b>样本超额：</b>候选平均减去市场平均，正值表示候选在样本中跑赢市场。</li></ul><p><b>正式结果：</b>预测发布后，再用下一交易日真实收盘行情检验的结果，请到“收盘验证”页面查看。</p></div><div class="grid backtest-grid"><MetricCard label="样本上涨率" :value="pct(data.latest_prediction.backtest_up_rate)"/><MetricCard label="候选平均" :value="pct(data.latest_prediction.backtest_avg_return)"/><MetricCard label="市场平均" :value="pct(data.latest_prediction.market_avg_return)"/><MetricCard label="样本超额" :value="pct(data.latest_prediction.excess_return)"/></div></div><div class="section"><h2>最新盘中 TopN</h2><DataTable :columns="cols" :rows="data.latest_intraday_groups"/></div></template></template>
